import{_ as c,C as s,o as h,c as p,a6 as i,j as t,a,E as o,w as l}from"./chunks/framework.CMg4qq8Q.js";const A=JSON.parse('{"title":"OAuth Authentication · Case File 07","description":"Inspect third-party sign-in handshakes, redirect URI validation gaps, CSRF state omissions, and token theft vectors.","frontmatter":{"title":"OAuth Authentication · Case File 07","description":"Inspect third-party sign-in handshakes, redirect URI validation gaps, CSRF state omissions, and token theft vectors."},"headers":[],"relativePath":"oauth/index.md","filePath":"oauth/index.md"}'),u={name:"oauth/index.md"},g={class:"wd-case"},m={class:"wd-step wd-step--break"};function w(f,e,v,k,_,y){const n=s("Term"),r=s("LabGroup"),d=s("TopicComplete");return h(),p("div",null,[e[16]||(e[16]=i('<h1 id="oauth-authentication-·-the-untrusted-handshake" tabindex="-1">OAuth Authentication · The Untrusted Handshake <a class="header-anchor" href="#oauth-authentication-·-the-untrusted-handshake" aria-label="Permalink to &quot;OAuth Authentication · The Untrusted Handshake&quot;">​</a></h1><p class="wd-section-lede">OAuth 2.0 was designed for <em>delegated authorization</em>—granting a service permission to read your calendar or photos without sharing your password. When modern websites bolt login authentication on top of OAuth, they create an intricate relay race between the browser, the application, and the identity provider where a single lax redirect rule can hand over the entire account.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Valet Parking Claim Ticket.</strong> Imagine pulling up to a luxury hotel and handing your car keys to the valet. The valet gives you a numbered claim ticket that lets anyone holding it retrieve your car. Now imagine you drop the claim ticket on the sidewalk, or the valet hands your car keys to anyone wearing a jacket similar to yours without checking their room number or identity. That is what happens when OAuth leaks authorization codes: anyone who intercepts that claim ticket can redeem it for full access to the victim&#39;s account.</p></div><h2 id="case-file-7-following-the-oauth-handshake-behind-the-scenes" tabindex="-1">Case File #7: Following the OAuth Handshake Behind the Scenes <a class="header-anchor" href="#case-file-7-following-the-oauth-handshake-behind-the-scenes" aria-label="Permalink to &quot;Case File #7: Following the OAuth Handshake Behind the Scenes&quot;">​</a></h2><p>Let&#39;s trace what happens when you click &quot;Log in with Social Account&quot; on an e-commerce website:</p>',5)),t("div",g,[e[4]||(e[4]=i('<div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You click &quot;Sign in with Social ID&quot;. Your browser redirects to the third-party provider&#39;s consent page: <code>oauth.provider.com/auth?client_id=store_123&amp;redirect_uri=https://store.com/oauth-callback&amp;response_type=code&amp;scope=email</code>. You click &quot;Authorize&quot;, and the provider redirects you back to the store with a code: <code>https://store.com/oauth-callback?code=SECRET_AUTH_CODE</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The store&#39;s backend server grabs the <code>code</code> from the redirect URL, connects directly to the identity provider&#39;s backstage API endpoint, exchanges the code for an access token, and fetches your email address to log you in:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Legitimate Registered Callback</span><span><span class="wd-code-input">Gold</span> = Tampered Parameter / Leakage Target</span></div><span class="wd-code-dev">redirect_uri=https://store.com/oauth-callback</span><span class="wd-code-input">/../../attacker.com/capture</span></div></div>',2)),t("div",m,[e[3]||(e[3]=t("span",{class:"wd-step__tag"},"💥 Step 3 · Where the Logic Breaks",-1)),t("p",null,[e[1]||(e[1]=a("The authorization server used loose pattern matching or path traversal on the ",-1)),o(n,{id:"oauth-redirect-uri"},{default:l(()=>[...e[0]||(e[0]=[a("redirect_uri",-1)])]),_:1}),e[2]||(e[2]=a(" parameter instead of enforcing an exact string match. As a result, the victim's secret authorization code is redirected straight into an external server log controlled by the attacker, allowing them to redeem the victim's login session!",-1))])]),e[5]||(e[5]=t("div",{class:"wd-step wd-step--fix"},[t("span",{class:"wd-step__tag"},"🛡️ Step 4 · How Developers Lock It Down"),t("p",null,[a("Enforce strict, exact string matching for all registered "),t("code",null,"redirect_uri"),a(" endpoints on the authorization server. Always include an unpredictable, cryptographically random "),t("code",null,"state"),a(" parameter bound to the user's browser session to prevent login CSRF, and adopt Authorization Code with PKCE (Proof Key for Code Exchange).")])],-1))]),e[17]||(e[17]=i('<h3 id="visual-comparison-exact-match-vs-regex-slip" tabindex="-1">Visual Comparison: Exact Match vs. Regex Slip <a class="header-anchor" href="#visual-comparison-exact-match-vs-regex-slip" aria-label="Permalink to &quot;Visual Comparison: Exact Match vs. Regex Slip&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The OAuth authorization server will only ever send the user&#39;s secret authorization code back to our official callback URL: <code>https://client.com/oauth-callback</code>.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The authorization server used a loose substring or prefix check, allowing <code>https://client.com/oauth-callback.attacker.com</code> or paths containing directory traversal to leak the code off-site.</p></div></div><h3 id="the-5-stages-of-the-oauth-authorization-code-flow" tabindex="-1">The 5 Stages of the OAuth Authorization Code Flow <a class="header-anchor" href="#the-5-stages-of-the-oauth-authorization-code-flow" aria-label="Permalink to &quot;The 5 Stages of the OAuth Authorization Code Flow&quot;">​</a></h3><p>Every standard OAuth login involves a coordinated multi-party handshake across the browser, client app, and authorization server:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Auth Request</strong> Browser sends client ID, scope, state, and <code>redirect_uri</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Consent &amp; Grant</strong> User logs in at provider and consents to share profile. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Code Redirect</strong> Provider redirects browser back with <code>?code=XYZ</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>4. Backchannel Token</strong> App server exchanges code for token via secure API. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Profile Minting</strong> App fetches user profile info and signs session cookie. </div></div><hr><h2 id="implicit-flow-and-redirect-uri-leakage" tabindex="-1">Implicit Flow and Redirect URI Leakage <a class="header-anchor" href="#implicit-flow-and-redirect-uri-leakage" aria-label="Permalink to &quot;Implicit Flow and Redirect URI Leakage&quot;">​</a></h2><p>In legacy OAuth implementations, applications often relied on the <strong>Implicit Grant Flow</strong>, where the authorization server delivers access tokens directly in the URL fragment (<code>#access_token=...</code>) to the browser instead of returning an authorization code to the backend.</p><p>Because tokens exist directly in the browser&#39;s address bar:</p><ul><li>Any open redirect or third-party script on the callback page can steal the token.</li><li>Web proxies, browser extensions, or <code>Referer</code> headers can leak the fragment to untrusted destinations.</li><li>If the application trusts profile emails sent directly from the client without verifying the server-side signature, an attacker can substitute any victim&#39;s email address and take over their account.</li></ul>',10)),o(r,{ids:"oauth-lab-oauth-authentication-bypass-via-oauth-implicit-flow, oauth-lab-oauth-account-hijacking-via-redirect-uri"}),e[18]||(e[18]=i('<details class="details custom-block"><summary>🔬 Under the Hood: Why URL Matching in OAuth Is Deceptively Difficult</summary><p>When validating incoming <code>redirect_uri</code> parameters, authorization servers frequently make subtle parsing errors:</p><ul><li><strong>Prefix Matching Flaws:</strong> Checking <code>uri.startsWith(&quot;https://example.com/callback&quot;)</code> erroneously approves <code>https://example.com/callback.attacker.com</code>.</li><li><strong>Domain Wildcards:</strong> Allowing <code>https://*.example.com/callback</code> enables any compromised subdomain, XSS flaw, or open redirect on any subdomain to capture codes.</li><li><strong>Path Traversal in Redirects:</strong> Sending <code>https://example.com/oauth/callback/../../open-redirect</code> resolves after validation, redirecting codes through an internal open redirect.</li></ul></details><hr><h2 id="profile-linking-and-missing-state-parameters" tabindex="-1">Profile Linking and Missing <code>state</code> Parameters <a class="header-anchor" href="#profile-linking-and-missing-state-parameters" aria-label="Permalink to &quot;Profile Linking and Missing `state` Parameters&quot;">​</a></h2><p>Many websites let users link their existing account to an external Google or GitHub identity for fast logins. The <code>state</code> parameter is designed as a CSRF token to prove that the person completing the OAuth flow is the same person who started it.</p><p>If an application omits or fails to validate the <code>state</code> parameter:</p><ol><li>An attacker starts the OAuth link flow with their own social media account and captures the authorization code before it is redeemed.</li><li>The attacker tricks a logged-in victim into clicking that callback URL.</li><li>The victim&#39;s application account becomes permanently bound to the <em>attacker&#39;s</em> social login identity, allowing the attacker to sign into the victim&#39;s account anytime!</li></ol>',6)),o(r,{ids:"oauth-lab-oauth-forced-oauth-profile-linking"}),e[19]||(e[19]=i('<hr><h2 id="token-theft-via-open-redirects-and-proxy-pages" tabindex="-1">Token Theft via Open Redirects and Proxy Pages <a class="header-anchor" href="#token-theft-via-open-redirects-and-proxy-pages" aria-label="Permalink to &quot;Token Theft via Open Redirects and Proxy Pages&quot;">​</a></h2><p>Even if the authorization server enforces strict <code>redirect_uri</code> validation, attackers look for secondary hops on the client website:</p><ul><li><strong>Chaining with Open Redirects:</strong> If the registered callback page contains an open redirect parameter (e.g. <code>https://client.com/callback?next=https://attacker.com</code>), the OAuth code or fragment lands on the client site and is instantly forwarded to the attacker.</li><li><strong>Proxy Pages &amp; PostMessage Leaks:</strong> If a website loads an external widget inside an iframe or uses <code>window.postMessage</code> without origin restrictions, the access token stored in the parent window can be harvested across origins.</li></ul>',4)),o(r,{ids:"oauth-lab-oauth-stealing-oauth-access-tokens-via-an-open-redirect, oauth-lab-oauth-stealing-oauth-access-tokens-via-a-proxy-page"}),e[20]||(e[20]=t("hr",null,null,-1)),e[21]||(e[21]=t("h2",{id:"dynamic-client-registration-and-ssrf",tabindex:"-1"},[a("Dynamic Client Registration and SSRF "),t("a",{class:"header-anchor",href:"#dynamic-client-registration-and-ssrf","aria-label":'Permalink to "Dynamic Client Registration and SSRF"'},"​")],-1)),e[22]||(e[22]=t("p",null,[a("The OpenID Connect standard includes an optional "),t("strong",null,"Dynamic Client Registration"),a(" specification that allows third-party client apps to register themselves automatically by submitting JSON metadata to "),t("code",null,"/register"),a(".")],-1)),e[23]||(e[23]=t("p",null,"If this endpoint is left publicly accessible without proper authentication and URL sanitization:",-1)),t("ul",null,[e[15]||(e[15]=t("li",null,"An attacker can register a malicious client application with custom redirect endpoints.",-1)),t("li",null,[e[9]||(e[9]=a("If the server accepts URLs for client logos (",-1)),e[10]||(e[10]=t("code",null,"logo_uri",-1)),e[11]||(e[11]=a(") or cryptographic keys (",-1)),e[12]||(e[12]=t("code",null,"jwks_uri",-1)),e[13]||(e[13]=a("), the server may fetch these URLs internally—introducing a high-impact ",-1)),t("strong",null,[e[7]||(e[7]=a("Server-Side Request Forgery (",-1)),o(n,{id:"ssrf-loopback"},{default:l(()=>[...e[6]||(e[6]=[a("SSRF",-1)])]),_:1}),e[8]||(e[8]=a(")",-1))]),e[14]||(e[14]=a(" vulnerability into internal infrastructure.",-1))])]),o(r,{ids:"oauth-lab-oauth-ssrf-via-openid-dynamic-client-registration"}),e[24]||(e[24]=i('<details class="details custom-block"><summary>⚙️ Engine Variations: How Major Identity Providers Handle Callbacks</summary><ul><li><strong>Google OAuth:</strong> Enforces byte-for-byte exact matching on <code>redirect_uri</code>. Wildcards are strictly disallowed (with an exception for <code>http://localhost</code> on loopback development).</li><li><strong>GitHub OAuth:</strong> Matches based on subpath hierarchies; query parameters are ignored during comparison, which can interact unexpectedly with client routers.</li><li><strong>Microsoft Azure AD / Entra:</strong> Supports wildcard redirects for Single Page Applications (SPAs), making misconfiguration and tenant-wide token leakage a recurring risk.</li><li><strong>Keycloak:</strong> Supports regex patterns in <code>Valid Redirect URIs</code>; entering <code>https://app.com/*</code> allows path traversal attacks.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Core Defensive Checklist:</strong> Always enforce exact, literal string matching for all redirect URIs on authorization servers. Always generate and validate a cryptographically secure, session-bound <code>state</code> parameter on every OAuth transaction to prevent login CSRF. Prefer the Authorization Code flow with PKCE over legacy Implicit flow, and never link third-party accounts without re-authenticating the current session.</p></div>',2)),o(d,{"topic-id":"oauth-authentication",label:"Mark OAuth complete"})])}const T=c(u,[["render",w]]);export{A as __pageData,T as default};
